const mutePackageNotificationsByToken = `-- name: MutePackageNotificationsByToken :one
UPDATE packages SET notify_on_download = 0
WHERE notify_mute_token = ?1 AND notify_mute_token IS NOT NULL
RETURNING id, created_by_user_id, name, message, verification_method, password_hash, expires_at, max_downloads, download_count, notify_on_download, status, created_at, notify_mute_token, preparation_status, preparation_bytes_total, preparation_bytes_done, preparation_error
`

// The mail's one-click opt-out. Idempotent: an already-muted package still
// matches, so a second click confirms rather than 404s. Returns the row so the
// page can name the package it just quietened.
func (q *Queries) MutePackageNotificationsByToken(ctx context.Context, notifyMuteToken sql.NullString) (Package, error) {
	row := q.db.QueryRowContext(ctx, mutePackageNotificationsByToken, notifyMuteToken)
	var i Package
	err := row.Scan(
		&i.ID,
		&i.CreatedByUserID,
		&i.Name,
		&i.Message,
		&i.VerificationMethod,
		&i.PasswordHash,
		&i.ExpiresAt,
		&i.MaxDownloads,
		&i.DownloadCount,
		&i.NotifyOnDownload,
		&i.Status,
		&i.CreatedAt,
		&i.NotifyMuteToken,
		&i.PreparationStatus,
		&i.PreparationBytesTotal,
		&i.PreparationBytesDone,
		&i.PreparationError,
	)
	return i, err
}

